coiIfControllerPreFECBERMantissa = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 639, 1, 1, 1, 1, 10), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 999))).setMaxAccess("readonly")
if mibBuilder.loadTexts: coiIfControllerPreFECBERMantissa.setStatus('current')
if mibBuilder.loadTexts: coiIfControllerPreFECBERMantissa.setDescription('This object gives the mantissa part of the Pre FEC BER or\n        correctable BER at any instance of time. It is represented in \n        one hundreths of a unit.The exponent part is defined in \n        coiIfControllerPreFECBERExponent\n\n        Pre FEC BER is the BER of the signal before it undergoes the \n        FEC algorithm.  FEC will correct errors upto a certain \n        Pre FEC BER beyond which the signal starts becoming \n        uncorrectable. Knowing the Pre FEC BER helps monitor system \n        health. Pre FEC BER is expressed in Scientific E notation \n        with two decimal places\n\n        Example: The value 235 represents the mantissa of 2.35')
coiIfControllerPreFECBERExponent = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 639, 1, 1, 1, 1, 11), Integer32().subtype(subtypeSpec=ValueRangeConstraint(-30, 0))).setMaxAccess("readonly")
if mibBuilder.loadTexts: coiIfControllerPreFECBERExponent.setStatus('current')
if mibBuilder.loadTexts: coiIfControllerPreFECBERExponent.setDescription('This object gives the exponent part of the Pre FEC BER or\n        correctable BER at any instance of time. It is  represented in \n        powers of 10. The mantissa part is defined in \n        coiIfControllerPreFECBERMantissa.\n\n        Pre FEC BER is the BER of the signal before it undergoes the \n        FEC algorithm. FEC will correct errors upto a certain \n        Pre FEC BER beyond which the signal starts becoming \n        uncorrectable. Knowing the Pre FEC BER helps monitor system \n        health. Pre FEC BER is expressed in Scientific E notation with \n        two decimal places\n        Example: The value -11 represents the exponent value of 10 to \n        the power of -11.')
coiIfControllerQFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 639, 1, 1, 1, 1, 12), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 9999))).setUnits('one hundredths of a dB').setMaxAccess("readonly")
if mibBuilder.loadTexts: coiIfControllerQFactor.setStatus('current')
